package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a correction added to a person unless it names, by number, a SETTLED claim of theirs. */
public class CheckCorrection {
    public void check(@Val ClaimInput input, @Val Person person, ClaimStore claims) throws InvalidSheetException {
        refuseUnsettled(claims, person.getSheetId(), person.getId(), input);
    }

    static void refuseUnsettled(ClaimStore claims, String sheetId, long personId, ClaimInput input)
            throws InvalidSheetException {
        if (!input.isCorrection()) {
            return;
        }
        Claim corrected = claims.findByNumber(sheetId, personId, input.corrects());
        if (corrected == null || corrected.getStatus() != ClaimStatus.SETTLED) {
            throw new InvalidSheetException("A correction must name a SETTLED claim of the same person");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim added with an external reference another claim on the sheet carries, compared without regard to case. */
public class CheckRef {
    public void check(@Val ClaimInput input, @Val Person person, ClaimStore claims) throws InvalidSheetException {
        refuseTaken(claims, person.getSheetId(), input, 0);
    }

    /** Refuses the claim's reference when a claim on the sheet other than {@code exceptId} carries it. */
    static void refuseTaken(ClaimStore claims, String sheetId, ClaimInput input, long exceptId)
            throws InvalidSheetException {
        if (input.ref() != null && claims.refTaken(sheetId, input.ref(), exceptId)) {
            throw new InvalidSheetException("The reference " + input.ref() + " is already used on the sheet");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Records a stored claim add: CLAIM_ADDED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>
 *  (then ref=<reference> when it has one, then tags=<tags, comma separated, sorted> when it has any),
 *  followed for a late entry by LATE_ENTRY naming the claim the same way. */
public class AuditClaimAdded {
    public void audit(@Val ClaimInput input, @Val Person person, @Val Claim claim, @Val Rollup before, Audit audit,
            RollupService rollups) {
        record(input, person, claim, before, audit, rollups);
    }

    static void record(ClaimInput input, Person person, Claim claim, Rollup before, Audit audit,
            RollupService rollups) {
        audit.record(AuditClaimEdited.line("CLAIM_ADDED", input, person, claim)
                + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
        if (claim.isLateEntry()) {
            audit.record(AuditClaimEdited.line("LATE_ENTRY", input, person, claim));
        }
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonStore store, Out<Person> personOut) throws InvalidSheetException {
        Person person = null;
        try {
            person = store.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (person == null) {
            throw new InvalidSheetException("No such person: " + personId);
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet change the app refuses; answered 400 with the message. */
public class InvalidSheetException extends Exception {
    public InvalidSheetException(String message) {
        super(message);
    }
}
